public enum FacetKindDto: Equatable, Hashable {

    case category
    case script
    case foundry
    case license
    case weight
    case width
    case feature
    case state
    case multipleVariants





}

#if compiler(>=6)
extension FacetKindDto: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFacetKindDto: FfiConverterRustBuffer {
    typealias SwiftType = FacetKindDto

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FacetKindDto {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .category

        case 2: return .script

        case 3: return .foundry

        case 4: return .license

        case 5: return .weight

        case 6: return .width

        case 7: return .feature

